// === Tab: mySketch ===
let shaderProg;
let timeStart;

const vert = `
  precision mediump float;
  attribute vec3 aPosition;
  varying vec2 vTexCoord;
  void main() {
    vTexCoord = (aPosition.xy + 1.0) * 0.5;
    gl_Position = vec4(aPosition, 1.0);
  }
`;

const frag = `
  precision mediump float;

  uniform float u_time;
  uniform bool u_noiseOn;
  uniform float u_noiseIntensity;

  uniform float u_zoom;

  uniform float u_glitchAmount;
  uniform float u_scanlineStrength;
  uniform float u_pixelSizeBase;
  uniform float u_rippleStrength;
  uniform float u_glowStrength;
  uniform float u_flickerStrength;

  uniform bool u_showRings;
  uniform float u_ringsIntensity;
  uniform float u_ringsFreq;

  uniform bool u_showWaves;
  uniform float u_wavesIntensity;

  uniform bool u_showSectors;
  uniform float u_sectorsIntensity;
  uniform float u_sectorsCount;

  uniform bool u_showScanlines;
  uniform bool u_showGrid;

  varying vec2 vTexCoord;

  // Value noise
  float noise(vec2 p){
    return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453123);
  }

  float fbm(vec2 p){
    float f = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for(int i=0; i<4; i++){
      f += amp * noise(p * freq);
      freq *= 2.0;
      amp *= 0.5;
    }
    return f;
  }

  float sec(float x) { return 1.0 / cos(x); }
  float csc(float x) { return 1.0 / sin(x); }
  float cot(float x) { return 1.0 / tan(x); }

  void main() {
    vec2 uv = vTexCoord - 0.5;
    uv *= u_zoom;

    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // === Rings ===
    float ringsPattern = 0.0;
    if(u_showRings){
      ringsPattern = sec(r * u_ringsFreq - u_time * 3.0) * 0.5 + 0.5;
    }
    vec3 ringsColor = vec3(ringsPattern) * u_ringsIntensity;

    // === Sectors ===
    float sectorsPattern = 0.0;
    if(u_showSectors){
      sectorsPattern = csc(a * u_sectorsCount + u_time * 2.0) * 0.5 + 0.5;
    }
    vec3 sectorsColor = vec3(sectorsPattern) * u_sectorsIntensity;

    // === Waves (displacement) ===
    if(u_showWaves){
      float waveDisplacementX = sin(uv.y * 10.0 + u_time * 3.0) * 0.02 * u_wavesIntensity;
      float waveDisplacementY = cos(uv.x * 10.0 + u_time * 3.0) * 0.02 * u_wavesIntensity;
      uv.x += waveDisplacementX;
      uv.y += waveDisplacementY;
    }

    // Scanlines
    float scanlines = u_showScanlines ? sin(uv.y * 4.0) * u_scanlineStrength : 0.0;

    // Distortion (always applied)
    float distortion = cot(uv.x * 5.0 + u_time) * 0.05;
    uv.y += distortion;

    // Chromatic Aberration
    float ca_offset = 0.005 * cos(u_time);
    vec3 chromatic = vec3(
      sin(r * 10.0 - u_time * 3.0 + ca_offset),
      sin(r * 10.0 - u_time * 3.0),
      sin(r * 10.0 - u_time * 3.0 - ca_offset)
    ) * 0.5 + 0.5;

    vec3 neonColor = vec3(0.5 + 0.5 * cos(u_time + vec3(0.0, 2.0, 4.0)));

    vec3 combinedPatterns = ringsColor + sectorsColor;

    vec3 baseColor = mix(neonColor, chromatic, combinedPatterns);

    vec3 finalColor = baseColor + scanlines;

    // Glitch effect
    float glitch = step(0.99, fract(sin(uv.y * 100.0 + u_time * 5.0) * 43758.5453123));
    uv.x += glitch * u_glitchAmount;

    // Glow
    vec3 glow = vec3(1.0, 0.5, 0.8) * smoothstep(0.3, 0.1, r);
    finalColor += glow * u_glowStrength;

    // Pixelation (controlled pixel size)
    float pixelSize = u_pixelSizeBase + 0.005 * cot(u_time * 2.0);
    uv = floor(uv / pixelSize) * pixelSize;

    // Ripple effect
    float ripple = sin(r * 15.0 - u_time * 5.0) * 0.2;
    uv.x += ripple * u_rippleStrength;
    uv.y += ripple * u_rippleStrength;

    // Grid overlay
    if(u_showGrid){
      float grid = mod(uv.x * 200.0, 1.0) > 0.9 || mod(uv.y * 20.0, 1.0) > 0.9 ? 0.3 : 0.0;
      finalColor += vec3(grid);
    }

    // Flickering
    float flicker = sin(u_time * 10.0) * u_flickerStrength;
    finalColor *= 1.0 + flicker;

    // Radial blur (vignette)
    finalColor = mix(finalColor, vec3(0.0), smoothstep(0.7, 1.2, r));

    // Starfield
    float starfield = step(0.995, fract(sin(dot(uv, vec2(12.9898, 78.233)) * 43758.5453 + u_time)));
    finalColor -= vec3(starfield * 0.8);

    // Plasma effect
    float plasma = cos(uv.x * 10.0 + u_time) * sin(uv.y * 10.0 + u_time) * 0.5 + 0.5;
    finalColor = mix(finalColor, vec3(1.0, 0.2, 0.3), plasma * 0.3);

    // Motion blur
    float motionBlur = smoothstep(0.0, 1.0, abs(csc(u_time * 0.5)));
    finalColor = mix(finalColor, vec3(0.0), motionBlur * 0.2);

    // Noise texture
    float noiseVal = u_noiseOn ? fbm(uv * 10.0 + u_time * 0.1) : 0.0;
    finalColor += vec3(noiseVal * u_noiseIntensity);

    // Water ripple
    float waterRipple = tan(r * 12.0 - u_time * 6.0) * 0.05;
    uv.x += waterRipple;
    uv.y += waterRipple;

    // Electric pulse
    float electricPulse = tan(u_time * 8.0 + uv.x * 15.0) * 0.3;
    finalColor -= vec3(electricPulse, electricPulse * 0.5, electricPulse * 0.2);

    // Final vignette
    float vignette = smoothstep(1.2, 0.5, r);
    gl_FragColor = vec4(finalColor * vignette, 1.0);
  }
`;

let gui;
let paused = false;
let pausedTime = 0;

let params = {
  // --- Pattern Controls ---
  showRings: true,
  ringsIntensity: 1.0,
  ringsFreq: 10.0,

  showWaves: true,
  wavesIntensity: 1.0,

  showSectors: true,
  sectorsIntensity: 1.0,
  sectorsCount: 6.0,

  showScanlines: true,
  showGrid: true,

  // --- Effects & Canvas Controls ---
  noiseOn: true,
  noiseIntensity: 0.1,

  zoom: 0.1,
  glitchAmount: 0.02,
  scanlineStrength: 0.1,
  pixelSizeBase: 0.01,
  rippleStrength: 0.1,
  glowStrength: 0.3,
  flickerStrength: 0.05,
  animationSpeed: 1.0,

  formFactor: 'Square',
  exportWidth: 800,
  exportHeight: 800,
  exportPixelDensity: 2,

  togglePause: function () {
    paused = !paused;
    if (paused) {
      pausedTime = millis();
    } else {
      timeStart += millis() - pausedTime;
    }
  },

  saveImage: function () {
    let oldW = width;
    let oldH = height;
    let oldPD = pixelDensity();

    resizeCanvas(params.exportWidth, params.exportHeight);
    pixelDensity(params.exportPixelDensity);
    redraw();

    saveCanvas(
      'background_' + nf(year(), 4) + nf(month(), 2) + nf(day(), 2),
      'png'
    );

    resizeCanvas(oldW, oldH);
    pixelDensity(oldPD);
  }
};

function setup() {
  if (params.formFactor === 'Square') {
    createCanvas(800, 800, WEBGL);
  } else {
    createCanvas(1280, 720, WEBGL);
  }
  noStroke();

  shaderProg = createShader(vert, frag);

  gui = new dat.GUI();

  // Patterns Group
  let patternFolder = gui.addFolder('Pattern Controls');
  patternFolder.add(params, 'showRings').name('Show Rings');
  patternFolder.add(params, 'ringsIntensity', 0, 2).step(0.01).name('Rings Intensity');
  patternFolder.add(params, 'ringsFreq', 1, 30).step(0.1).name('Rings Frequency');
  patternFolder.add(params, 'showWaves').name('Show Waves');
  patternFolder.add(params, 'wavesIntensity', 0, 2).step(0.01).name('Waves Intensity');
  patternFolder.add(params, 'showSectors').name('Show Sectors');
  patternFolder.add(params, 'sectorsIntensity', 0, 2).step(0.01).name('Sectors Intensity');
  patternFolder.add(params, 'sectorsCount', 1, 30).step(1).name('Sectors Count');
  patternFolder.add(params, 'showScanlines').name('Show Scanlines');
  patternFolder.add(params, 'showGrid').name('Show Grid');
  patternFolder.open();

  // Effects Group and UI
  let effectFolder = gui.addFolder('Effects & Canvas Controls');
  effectFolder.add(params, 'noiseOn').name('Noise On');
  effectFolder.add(params, 'noiseIntensity', 0, 1).step(0.01).name('Noise Intensity');
  effectFolder.add(params, 'zoom', 0.01, 1).step(0.01).name('Scale (Zoom)');
  effectFolder.add(params, 'glitchAmount', 0, 0.1).step(0.001).name('Glitch Amount');
  effectFolder.add(params, 'scanlineStrength', 0, 0.3).step(0.005).name('Scanline Strength');
  effectFolder.add(params, 'pixelSizeBase', 0.001, 0.05).step(0.001).name('Pixel Size Base');
  effectFolder.add(params, 'rippleStrength', 0, 0.3).step(0.005).name('Ripple Strength');
  effectFolder.add(params, 'glowStrength', 0, 1).step(0.01).name('Glow Strength');
  effectFolder.add(params, 'flickerStrength', 0, 0.1).step(0.001).name('Flicker Strength');
  effectFolder.add(params, 'animationSpeed', 0, 3).step(0.01).name('Animation Speed');
  effectFolder.add(params, 'formFactor', ['Square', 'Horizontal']).name('Form Factor').onChange(() => {
    if (params.formFactor === 'Square') {
      resizeCanvas(800, 800);
      params.exportWidth = 800;
      params.exportHeight = 800;
    } else {
      resizeCanvas(1280, 720);
      params.exportWidth = 1280;
      params.exportHeight = 720;
    }
  });

  effectFolder.add(params, 'exportWidth', 200, 3840).step(10).name('Export Width (px)');
  effectFolder.add(params, 'exportHeight', 200, 2160).step(10).name('Export Height (px)');
  effectFolder.add(params, 'exportPixelDensity', 1, 4).step(1).name('Export Pixel Density');
  effectFolder.add(params, 'togglePause').name('Pause Animation');
  effectFolder.add(params, 'saveImage').name('Save PNG');
  effectFolder.open();

  timeStart = millis();
  pixelDensity(2);
  frameRate(60);
}

function draw() {
  shader(shaderProg);

  let elapsed = paused ? (pausedTime - timeStart) : (millis() - timeStart);
  let time = (elapsed / 1000.0) * params.animationSpeed;

  shaderProg.setUniform('u_time', time);
  shaderProg.setUniform('u_noiseOn', params.noiseOn);
  shaderProg.setUniform('u_noiseIntensity', params.noiseIntensity);
  shaderProg.setUniform('u_zoom', params.zoom);
  shaderProg.setUniform('u_glitchAmount', params.glitchAmount);
  shaderProg.setUniform('u_scanlineStrength', params.scanlineStrength);
  shaderProg.setUniform('u_pixelSizeBase', params.pixelSizeBase);
  shaderProg.setUniform('u_rippleStrength', params.rippleStrength);
  shaderProg.setUniform('u_glowStrength', params.glowStrength);
  shaderProg.setUniform('u_flickerStrength', params.flickerStrength);

  shaderProg.setUniform('u_showRings', params.showRings);
  shaderProg.setUniform('u_ringsIntensity', params.ringsIntensity);
  shaderProg.setUniform('u_ringsFreq', params.ringsFreq);
  shaderProg.setUniform('u_showWaves', params.showWaves);
  shaderProg.setUniform('u_wavesIntensity', params.wavesIntensity);
  shaderProg.setUniform('u_showSectors', params.showSectors);
  shaderProg.setUniform('u_sectorsIntensity', params.sectorsIntensity);
  shaderProg.setUniform('u_sectorsCount', params.sectorsCount);
  shaderProg.setUniform('u_showScanlines', params.showScanlines);
  shaderProg.setUniform('u_showGrid', params.showGrid);

  beginShape();
  vertex(-1, -1, 0);
  vertex(1, -1, 0);
  vertex(1, 1, 0);
  vertex(-1, 1, 0);
  endShape(CLOSE);
}

function keyPressed() {
  if (key === 's' || key === 'S') {
    params.saveImage();
  }
  if (key === 'p' || key === 'P') {
    params.togglePause();
  }
}

